workflow.input_script:
function toArray(value) {
  if (Array.isArray(value)) return value;
  if (value === undefined || value === null || value === '') return [];
  return [value];
}
var owners = toArray(input.owner);
var names = toArray(input.name);
if (!owners.length || !names.length || owners.length !== names.length) {
  throw new Error('owner and name must be non-empty arrays of equal length');
}
var repoIds = [];
var seen = {};
for (var i = 0; i < owners.length; i++) {
  var owner = String(owners[i] == null ? '' : owners[i]).trim();
  var name = String(names[i] == null ? '' : names[i]).trim();
  if (!owner || !name) throw new Error('owner and name values must not be empty');
  var id = owner.replace(/\//g, ':') + '/' + name;
  if (!seen[id]) { seen[id] = true; repoIds.push(id); }
}
var from = Number(input.from);
var to = Number(input.to);
if (!isFinite(from) || !isFinite(to) || from < 0 || to < from) {
  throw new Error('valid from and to Unix timestamps are required');
}
var rawBlueprints = toArray(input.blueprintid);
var blueprintIds = [];
for (var j = 0; j < rawBlueprints.length; j++) {
  var idNumber = Number(rawBlueprints[j]);
  if (!isFinite(idNumber) || idNumber <= 0 || Math.floor(idNumber) !== idNumber) {
    throw new Error('blueprintid must contain positive integers');
  }
  blueprintIds.push(idNumber);
}
({ repo_ids: repoIds, from: from, to: to,
   blueprint_ids: blueprintIds.length ? blueprintIds : [-1],
   has_blueprint: blueprintIds.length ? 1 : 0, requested_count: names.length })

workflow.output_script:
function round1(value) { return Math.round(value * 10) / 10; }
function day(value) { return String(value).slice(0, 10); }
function uniqueRows(rows, keyFn) {
  var seen = {}, out = [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i] || {};
    var key = keyFn(row);
    if (key && !seen[key]) { seen[key] = true; out.push(row); }
  }
  return out;
}
var daily = uniqueRows(results.daily_coverage || [], function (r) {
  return r.repo_id && r.date_val ? r.repo_id + '|' + day(r.date_val) : '';
});
if (!daily.length) {
  ({ error: 'No daily coverage data found for the selected period' });
} else {
  var multi = Number(input.requested_count) > 1;
  var patches = uniqueRows(results.daily_patch || [], function (r) {
    return r.repo_id && r.date_val ? r.repo_id + '|' + day(r.date_val) : '';
  });
  var flagRows = uniqueRows(results.daily_flags || [], function (r) {
    return r.repo_id && r.date_val && r.flag_name ? r.repo_id + '|' + day(r.date_val) + '|' + r.flag_name : '';
  });
  var dailyByDate = {}, patchByDate = {}, flagsByDate = {}, knownByRepo = {}, known = {};
  for (var i = 0; i < daily.length; i++) {
    var d = day(daily[i].date_val), repo = String(daily[i].repo_id);
    if (!dailyByDate[d]) dailyByDate[d] = {};
    dailyByDate[d][repo] = Number(daily[i].daily_coverage_avg);
  }
  for (var p = 0; p < patches.length; p++) {
    var pd = day(patches[p].date_val), pr = String(patches[p].repo_id);
    if (!patchByDate[pd]) patchByDate[pd] = {};
    patchByDate[pd][pr] = Number(patches[p].daily_patch_avg);
  }
  for (var f = 0; f < flagRows.length; f++) {
    var row = flagRows[f], fd = day(row.date_val), fr = String(row.repo_id), name = String(row.flag_name);
    if (!flagsByDate[fd]) flagsByDate[fd] = {};
    if (!flagsByDate[fd][fr]) flagsByDate[fd][fr] = {};
    flagsByDate[fd][fr][name] = { avg: Number(row.daily_flag_avg), lines: Number(row.total_lines) };
    if (Number(row.total_lines) > 0) {
      if (!knownByRepo[fr]) knownByRepo[fr] = {};
      knownByRepo[fr][name] = true;
      known[name] = true;
    }
  }
  var dates = Object.keys(dailyByDate).sort();
  var latest = {}, overall = [], patch = [];
  for (var x = 0; x < dates.length; x++) {
    var date = dates[x], values = dailyByDate[date], repos = Object.keys(values);
    for (var r = 0; r < repos.length; r++) latest[repos[r]] = values[repos[r]];
    var lastValues = Object.keys(latest).map(function (id) { return latest[id]; });
    var total = 0;
    for (var v = 0; v < lastValues.length; v++) total += lastValues[v];
    overall.push(round1(total / lastValues.length));
    var patchRepos = patchByDate[date] || {}, patchIds = Object.keys(patchRepos), patchTotal = 0;
    for (var q = 0; q < patchIds.length; q++) patchTotal += patchRepos[patchIds[q]];
    patch.push(patchIds.length ? round1(patchTotal / patchIds.length) : null);
  }
  var flagNames = Object.keys(known).sort();
  var colors = [
    ['rgb(153, 102, 255)', 'rgba(153, 102, 255, 0.7)'],
    ['rgb(255, 159, 64)', 'rgba(255, 159, 64, 0.7)'],
    ['rgb(75, 192, 192)', 'rgba(75, 192, 192, 0.7)'],
    ['rgb(255, 99, 132)', 'rgba(255, 99, 132, 0.7)'],
    ['rgb(54, 162, 235)', 'rgba(54, 162, 235, 0.7)']
  ];
  var datasets = [{
    label: 'Overall Coverage (%)', data: overall, showLine: false,
    pointRadius: 6, pointHoverRadius: 8,
    pointBackgroundColor: 'rgba(0, 102, 204, 0.7)',
    pointBorderColor: 'rgba(0, 102, 204, 1)', pointBorderWidth: 1,
    backgroundColor: 'rgba(0, 102, 204, 0.7)'
  }];
  if (!multi) {
    for (var n = 0; n < flagNames.length; n++) {
      var flag = flagNames[n], series = [], color = colors[n % colors.length];
      for (var z = 0; z < dates.length; z++) {
        var repoMap = flagsByDate[dates[z]] || {}, flagRepos = Object.keys(repoMap), sum = 0, count = 0;
        for (var a = 0; a < flagRepos.length; a++) {
          var entry = repoMap[flagRepos[a]][flag];
          if (entry && entry.lines > 0) { sum += entry.avg; count++; }
        }
        series.push(count ? round1(sum / count) : null);
      }
      datasets.push({
        label: flag + ' (%)', data: series, fill: false,
        borderColor: color[0], borderWidth: 2, pointRadius: 3,
        pointHoverRadius: 5, pointBackgroundColor: color[1], tension: 0.3
      });
    }
  }
  var goal = 80, defaultGoal = true, config = results.coverage_goals || [], targets = [];
  var seenGoals = {};
  for (var g = 0; g < config.length; g++) {
    var cfg = config[g] || {};
    if (!cfg.repo_id || seenGoals[cfg.repo_id]) continue;
    seenGoals[cfg.repo_id] = true;
    if (cfg.patch_target != null && isFinite(Number(cfg.patch_target))) targets.push(Number(cfg.patch_target));
  }
  if (targets.length) {
    var goalSum = 0;
    for (var t = 0; t < targets.length; t++) goalSum += targets[t];
    goal = multi ? round1(goalSum / targets.length) : targets[0];
    defaultGoal = false;
  }
  datasets.push({
    label: 'Patch Coverage (%)', data: patch, fill: false,
    borderColor: 'rgb(62, 134, 53)', borderWidth: 2, borderDash: [5, 5],
    pointRadius: 4, pointHoverRadius: 6,
    pointBackgroundColor: 'rgba(62, 134, 53, 0.7)', tension: 0.3
  });
  datasets.push({
    label: 'Patch Goal (' + goal + '%' + (defaultGoal ? ' — default' : '') + ')',
    data: dates.map(function () { return goal; }), fill: false,
    borderColor: defaultGoal ? 'rgba(150, 150, 150, 0.35)' : 'rgba(62, 134, 53, 0.35)',
    borderWidth: 1.5, borderDash: defaultGoal ? [4, 6] : [8, 4],
    pointRadius: 0, pointHoverRadius: 0, tension: 0, isGoalLine: true
  });
  var goalDescription = defaultGoal
    ? '<br><b>Patch Goal (' + goal + '% — default)</b> — recommended minimum; configure in codecov.yml to set a repo-specific target (gray dashed).'
    : '<br><b>Patch Goal (' + goal + '%)</b> — patch coverage target from codecov.yml (green dashed).';
  var description = multi
    ? '<b>Avg Overall Coverage</b> — daily average across selected repos (dots).<br><b>Avg Patch Coverage</b> — average patch coverage across repos (dashed).' + goalDescription
    : '<b>Overall Coverage</b> — daily coverage across all repos (dots).<br><b>Per-flag lines</b> — coverage from each test type.<br><b>Patch Coverage</b> — coverage of new or changed code (dashed).' + goalDescription;
  var output = {
    type: 'line', label: 'Coverage Trend (%)', description: description,
    flags: multi ? [] : flagNames,
    data: { labels: dates, datasets: datasets,
      options: { scales: { y: { min: 0, max: 100, title: { display: true, text: 'Coverage (%)' } } } } }
  };
  var pipeline = results.last_pipeline || [];
  if (pipeline.length && Number(pipeline[0].lastupdate) > 0) output.lastupdate = Number(pipeline[0].lastupdate);
  if (flagRows.length && !multi) {
    var stale = {}, maxGap = 0, flagDates = Object.keys(flagsByDate).sort(), knownRepos = Object.keys(knownByRepo);
    for (var k = 0; k < knownRepos.length; k++) {
      var knownRepo = knownRepos[k], repoFlags = Object.keys(knownByRepo[knownRepo]);
      if (repoFlags.length <= 1) continue;
      var repoDates = flagDates.filter(function (dt) { return !!flagsByDate[dt][knownRepo]; });
      if (!repoDates.length) continue;
      var lastDate = repoDates[repoDates.length - 1], completeDate = '';
      for (var h = repoDates.length - 1; h >= 0; h--) {
        var entries = flagsByDate[repoDates[h]][knownRepo], complete = true;
        for (var m = 0; m < repoFlags.length; m++) {
          if (!entries[repoFlags[m]] || entries[repoFlags[m]].lines <= 0) complete = false;
        }
        if (complete) { completeDate = repoDates[h]; break; }
      }
      if (completeDate && completeDate !== lastDate) {
        var gap = Math.round((Date.parse(lastDate) - Date.parse(completeDate)) / 86400000);
        if (gap > 7) {
          maxGap = Math.max(maxGap, gap);
          var lastEntries = flagsByDate[lastDate][knownRepo];
          for (var s = 0; s < repoFlags.length; s++) {
            var flagName = repoFlags[s];
            if (!lastEntries[flagName] || lastEntries[flagName].lines <= 0) stale[flagName] = true;
          }
        }
      }
    }
    var staleNames = Object.keys(stale).sort();
    if (staleNames.length) {
      output.warning = '⚠ Coverage flag(s) ' + staleNames.map(function (name) { return '"' + name + '"'; }).join(', ') +
        ' have not reported data for ' + maxGap + ' days. Overall coverage may be lower than expected.';
    }
  }
  output;
}
